import {
  Archive, ArrowLeft, ArrowRight, ArrowUpRight, BarChart3, Boxes, Check, CheckCircle2, ChevronDown, CircleAlert,
  Clock3, CreditCard, Database, ExternalLink, FileClock, FilePenLine, Filter, LayoutDashboard,
  FolderTree, Link2, LockKeyhole, LogOut, PackageCheck, Plus, RefreshCcw, Search, ShieldCheck, Star, Tag, Trash2, Truck, UsersRound, X,
} from "lucide-react";
import { useMemo, useState } from "react";
import { Link } from "wouter";
import { toast } from "sonner";
import SiteNav from "@/components/SiteNav";
import { useAuth } from "@/_core/hooks/useAuth";
import { trpc } from "@/lib/trpc";

type Tab = "overview" | "products" | "orders" | "deliveries" | "categories" | "coupons" | "reviews" | "system";
type ProductForm = {
  name: string; slug: string; tagline: string; description: string; category: string; categoryId: string; price: string; currency: string;
  heroImage: string; demoUrl: string; sourceRepoUrl: string; sourceRepoBranch: string; provisioningMode: "manual" | "external" | "native"; requirements: string; license: string; included: string; faq: string; status: "draft" | "published" | "archived";
  featuresText: string; techText: string;
};

const emptyForm: ProductForm = { name: "", slug: "", tagline: "", description: "", category: "", categoryId: "", price: "", currency: "EUR", heroImage: "", demoUrl: "", sourceRepoUrl: "", sourceRepoBranch: "main", provisioningMode: "manual", requirements: "", license: "", included: "", faq: "", status: "draft", featuresText: "", techText: "" };
const statusStyles: Record<string, string> = { published: "bg-emerald-400/10 text-emerald-300", draft: "bg-amber-400/10 text-amber-200", archived: "bg-white/10 text-white/45", pending: "bg-amber-400/10 text-amber-200", payment_verified: "bg-sky-400/10 text-sky-200", paid: "bg-emerald-400/10 text-emerald-300", fulfilled: "bg-cyan-400/10 text-cyan-200", cancelled: "bg-red-400/10 text-red-300", queued: "bg-white/10 text-white/55", provisioning: "bg-sky-400/10 text-sky-200", ready: "bg-emerald-400/10 text-emerald-300", blocked: "bg-red-400/10 text-red-300" };

function StatusPill({ status }: { status: string }) { return <span className={`inline-flex items-center rounded-full px-2.5 py-1 font-mono text-[9px] uppercase tracking-[.14em] ${statusStyles[status] ?? "bg-white/10 text-white/55"}`}>{status.replace("_", " ")}</span>; }
function AdminButton({ children, onClick, disabled, tone = "muted", type = "button" }: { children: React.ReactNode; onClick?: () => void; disabled?: boolean; tone?: "muted" | "light" | "danger"; type?: "button" | "submit" }) { const toneClass = tone === "light" ? "bg-white text-[#06111f]" : tone === "danger" ? "border-red-400/25 text-red-300 hover:bg-red-400/10" : "border-white/15 text-white/65 hover:border-white/35 hover:text-white"; return <button type={type} onClick={onClick} disabled={disabled} className={`inline-flex items-center justify-center gap-2 rounded-xl border px-3.5 py-2.5 text-xs font-semibold transition disabled:cursor-wait disabled:opacity-45 ${toneClass}`}>{children}</button>; }

function ProductEditor({ initial, onClose, onSaved }: { initial?: any; onClose: () => void; onSaved: () => void }) {
  const [form, setForm] = useState<ProductForm>(() => initial ? { name: initial.name, slug: initial.slug, tagline: initial.tagline, description: initial.description, category: initial.category, categoryId: String(initial.categoryId ?? ""), price: String(initial.price), currency: initial.currency, heroImage: initial.heroImage, demoUrl: initial.demoUrl ?? "", sourceRepoUrl: initial.sourceRepoUrl ?? "", sourceRepoBranch: initial.sourceRepoBranch ?? "main", provisioningMode: initial.provisioningMode ?? "manual", requirements: initial.requirements ?? "", license: initial.license ?? "", included: initial.included ?? "", faq: initial.faq ?? "", status: initial.status, featuresText: (initial.features ?? []).map((feature: any) => `${feature.title} | ${feature.description}`).join("\n"), techText: (initial.techStack ?? []).map((stack: any) => stack.name).join(", ") } : emptyForm);
  const utils = trpc.useUtils();
  const categoriesQuery = trpc.admin.categories.useQuery();
  const create = trpc.admin.productCreate.useMutation({ onSuccess: () => { toast.success("Product created"); utils.admin.products.invalidate(); utils.admin.overview.invalidate(); onSaved(); onClose(); }, onError: (e) => toast.error("Product was not saved", { description: e.message }) });
  const update = trpc.admin.productUpdate.useMutation({ onSuccess: () => { toast.success("Product updated"); utils.admin.products.invalidate(); utils.admin.overview.invalidate(); onSaved(); onClose(); }, onError: (e) => toast.error("Product was not updated", { description: e.message }) });
  const faqGenerate = trpc.admin.productFaqGenerate.useMutation({ onSuccess: (faq) => { set("faq", faq); toast.success("FAQ generated"); }, onError: (e) => toast.error("FAQ generation failed", { description: e.message }) });
  const set = (key: keyof ProductForm, value: string) => setForm((current) => ({ ...current, [key]: value }));
  const submit = (event: React.FormEvent) => { event.preventDefault(); const features = form.featuresText.split("\n").map((line) => line.trim()).filter(Boolean).map((line) => { const [title, ...description] = line.split("|"); return { title: title.trim(), description: description.join("|").trim() || title.trim() }; }); const techStack = form.techText.split(",").map((name) => name.trim()).filter(Boolean).map((name) => ({ name, category: null })); const selectedCategory = categoriesQuery.data?.find((category) => String(category.id) === form.categoryId); const data = { name: form.name, slug: form.slug, tagline: form.tagline, description: form.description, category: selectedCategory?.name ?? form.category, categoryId: Number(form.categoryId), price: form.price, currency: form.currency, heroImage: form.heroImage, demoUrl: form.demoUrl || null, sourceRepoUrl: form.sourceRepoUrl || null, sourceRepoBranch: form.sourceRepoBranch || "main", provisioningMode: form.provisioningMode, requirements: form.requirements || null, license: form.license || null, included: form.included || null, faq: form.faq || null, status: form.status, features, techStack }; if (initial) update.mutate({ productId: initial.id, data }); else create.mutate(data); };
  const busy = create.isPending || update.isPending;
  const fields: Array<[keyof ProductForm, string, string, boolean]> = [["name", "Product name", "Atlas Studio", false], ["slug", "Slug", "atlas-studio", false], ["tagline", "Tagline", "An editorial home for spaces that matter.", false], ["price", "Price", "1280.00", false], ["currency", "Currency", "EUR", false], ["heroImage", "Hero image path", "/assets/product-mono.svg", false], ["demoUrl", "Live demo URL", "https://demo.example.com", false], ["sourceRepoUrl", "GitHub source repository", "https://github.com/owner/repo", false], ["sourceRepoBranch", "Source branch", "main", false]];
  return <div className="fixed inset-0 z-50 overflow-y-auto bg-[#06111f]/90 p-4 backdrop-blur-md md:p-10"><div className="mx-auto max-w-4xl rounded-[28px] border border-white/15 bg-[#0a1b2d] p-6 shadow-2xl md:p-9"><div className="mb-8 flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#83c2ff]">{initial ? "Edit product" : "New product"}</div><h2 className="mt-3 text-3xl font-semibold tracking-[-.06em] text-white">{initial ? initial.name : "Create a website product"}</h2></div><button type="button" onClick={onClose} className="rounded-full border border-white/15 p-2 text-white/50 hover:text-white"><X size={17} /></button></div><form onSubmit={submit} className="space-y-6"><div className="grid gap-4 md:grid-cols-2">{fields.map(([key, label, placeholder]) => <label key={key} className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">{label}</span><input required={!['demoUrl'].includes(key)} value={form[key]} onChange={(event) => set(key, event.target.value)} placeholder={placeholder} className="w-full rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm text-white outline-none transition focus:border-[#83c2ff]/70" /></label>)}</div><div className="grid gap-4 md:grid-cols-2"><label className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Provisioning mode</span><select value={form.provisioningMode} onChange={(event) => set("provisioningMode", event.target.value as ProductForm["provisioningMode"])} className="w-full rounded-xl border border-white/10 bg-[#0b1b2d] px-3.5 py-3 text-sm text-white"><option value="manual">Manual handover</option><option value="external">External provisioning worker</option><option value="native">NUMI native GitHub + Vercel</option></select></label><div className="rounded-xl border border-white/10 bg-white/[.03] p-3 text-xs leading-5 text-white/45">Native mode creates an independent private GitHub repository and connects it to a Vercel project after verified payment. Provider credentials stay server-side.</div></div><div className="rounded-2xl border border-[#83c2ff]/20 bg-[#2d7ff9]/[.06] p-4"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><div className="font-mono text-[10px] uppercase tracking-[.14em] text-[#83c2ff]">AI content assistant</div><p className="mt-1 text-xs leading-5 text-white/45">Generate a practical FAQ from the product fields, then review and edit it before saving.</p></div><AdminButton onClick={() => faqGenerate.mutate({ name: form.name, tagline: form.tagline, description: form.description, category: form.category, price: form.price || "0", currency: form.currency, requirements: form.requirements || null, included: form.included || null, license: form.license || null, techStack: form.techText.split(",").map((item) => item.trim()).filter(Boolean) })} disabled={faqGenerate.isPending}>{faqGenerate.isPending ? "Generating…" : "Generate FAQ"}</AdminButton></div></div><label className="block space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Category</span><select required value={form.categoryId} onChange={(event) => set("categoryId", event.target.value)} className="w-full rounded-xl border border-white/10 bg-[#0b1b2d] px-3.5 py-3 text-sm text-white outline-none focus:border-[#83c2ff]/70"><option value="">Choose a category</option>{(categoriesQuery.data ?? []).filter((category) => category.status === "published").map((category) => <option key={category.id} value={category.id}>{category.name}</option>)}</select></label><label className="block space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Status</span><select value={form.status} onChange={(event) => set("status", event.target.value)} className="w-full rounded-xl border border-white/10 bg-[#0b1b2d] px-3.5 py-3 text-sm text-white outline-none"><option value="draft">Draft</option><option value="published">Published</option><option value="archived">Archived</option></select></label><div className="grid gap-4 md:grid-cols-2"><label className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Description</span><textarea required value={form.description} onChange={(event) => set("description", event.target.value)} rows={6} className="w-full resize-none rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm leading-6 text-white outline-none focus:border-[#83c2ff]/70" /></label><label className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Features — one per line: title | description</span><textarea value={form.featuresText} onChange={(event) => set("featuresText", event.target.value)} rows={6} placeholder="Editorial layout system | Long-form pages..." className="w-full resize-none rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm leading-6 text-white outline-none focus:border-[#83c2ff]/70" /></label></div><div className="grid gap-4 md:grid-cols-2"><label className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Requirements</span><textarea value={form.requirements} onChange={(event) => set("requirements", event.target.value)} rows={4} className="w-full resize-none rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm leading-6 text-white outline-none focus:border-[#83c2ff]/70" /></label><label className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Included / license</span><textarea value={`${form.included}\n---LICENSE---\n${form.license}`} onChange={(event) => { const [included, license = ""] = event.target.value.split("\n---LICENSE---\n"); setForm((current) => ({ ...current, included, license })); }} rows={4} className="w-full resize-none rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm leading-6 text-white outline-none focus:border-[#83c2ff]/70" /></label></div><label className="block space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">FAQ — review before saving</span><textarea value={form.faq} onChange={(event) => set("faq", event.target.value)} rows={8} placeholder="Q: Who is this for?\nA: ..." className="w-full resize-y rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm leading-6 text-white outline-none focus:border-[#83c2ff]/70" /></label><label className="block space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Tech stack — comma separated</span><input value={form.techText} onChange={(event) => set("techText", event.target.value)} placeholder="React, TypeScript, Tailwind CSS" className="w-full rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm text-white outline-none focus:border-[#83c2ff]/70" /></label><div className="flex justify-end gap-3 border-t border-white/10 pt-6"><AdminButton onClick={onClose}>Cancel</AdminButton><AdminButton type="submit" tone="light" disabled={busy}>{busy ? "Saving…" : initial ? "Save changes" : "Create product"}</AdminButton></div></form></div></div>;
}

function Overview({ overview, onNavigate }: { overview: any; onNavigate: (tab: Tab) => void }) {
  const cards = [{ label: "Published products", value: overview?.products ?? 0, icon: Boxes, tab: "products" as Tab }, { label: "Orders", value: overview?.orders ?? 0, icon: CreditCard, tab: "orders" as Tab }, { label: "Paid orders", value: overview?.paidOrders ?? 0, icon: CheckCircle2, tab: "orders" as Tab }, { label: "Customers", value: overview?.customers ?? 0, icon: UsersRound, tab: "orders" as Tab }, { label: "Verified revenue", value: `€${overview?.revenue ?? "0.00"}`, icon: BarChart3, tab: "orders" as Tab }, { label: "Product views", value: overview?.productViews ?? 0, icon: ExternalLink, tab: "products" as Tab }, { label: "Demo opens", value: overview?.demoOpens ?? 0, icon: ArrowUpRight, tab: "products" as Tab }];
  return <div className="space-y-8"><section className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{cards.map(({ label, value, icon: Icon, tab }) => <button type="button" key={label} onClick={() => onNavigate(tab)} className="glass rounded-2xl p-6 text-left transition hover:-translate-y-0.5 hover:border-[#83c2ff]/40"><Icon className="mb-8 text-[#83c2ff]" size={21} /><div className="font-mono text-[10px] uppercase tracking-[.16em] text-white/35">{label}</div><div className="mt-3 text-3xl font-semibold text-white">{value}</div></button>)}</section><section className="grid gap-5 lg:grid-cols-[1.1fr_.9fr]"><div className="glass rounded-[28px] p-7 md:p-9"><div className="flex items-center justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.18em] text-white/35">Workflow</div><h2 className="mt-3 text-2xl font-semibold text-white">Operations surface</h2></div><FileClock className="text-white/30" size={21} /></div><div className="mt-8 space-y-3">{[["Product catalog", "Create, edit, publish, archive", "products"], ["Order control", "Search payment and fulfillment state", "orders"], ["Delivery center", "Provisioning checklist and handover links", "deliveries"]].map(([title, detail, tab]) => <button type="button" onClick={() => onNavigate(tab as Tab)} key={title} className="flex w-full items-center justify-between rounded-2xl bg-white/[.04] p-4 text-left transition hover:bg-white/[.07]"><div><div className="text-sm font-semibold text-white">{title}</div><div className="mt-1 text-xs text-white/40">{detail}</div></div><ArrowRight size={16} className="text-white/35" /></button>)}</div></div><div className="glass rounded-[28px] p-7 md:p-9"><Database className="mb-8 text-[#ef8b65]" size={23} /><div className="font-mono text-[10px] uppercase tracking-[.18em] text-white/35">Guardrails</div><h2 className="mt-3 text-2xl font-semibold text-white">Payment stays verified.</h2><p className="mt-4 text-sm leading-7 text-white/50">Admin can inspect every order and manage fulfillment, but a payment is never marked paid from the browser. Provider webhooks remain the source of truth.</p><div className="mt-7 flex items-center gap-2 text-xs text-white/60"><ShieldCheck size={15} className="text-[#83c2ff]" /> Audit log records owner actions.</div></div></section></div>;
}

function ProductsPanel({ onEdit }: { onEdit: (product?: any) => void }) {
  const query = trpc.admin.products.useQuery();
  const utils = trpc.useUtils();
  const demoCheck = trpc.admin.productDemoCheck.useMutation({ onSuccess: (result) => { toast.success(result.status === "healthy" ? "Live demo verified" : "Demo check completed", { description: result.status }); utils.admin.products.invalidate(); }, onError: (e) => toast.error("Demo check failed", { description: e.message }) });
  const statusMutation = trpc.admin.productStatus.useMutation({ onSuccess: () => { toast.success("Product status updated"); utils.admin.products.invalidate(); utils.admin.overview.invalidate(); }, onError: (e) => toast.error("Status update failed", { description: e.message }) });
  const deleteMutation = trpc.admin.productDelete.useMutation({ onSuccess: () => { toast.success("Product deleted"); utils.admin.products.invalidate(); utils.admin.overview.invalidate(); }, onError: (e) => toast.error("Product was not deleted", { description: e.message }) });
  const products = query.data ?? [];
  const [search, setSearch] = useState("");
  const [filter, setFilter] = useState("all");
  const visibleProducts = useMemo(() => products.filter((product: any) => `${product.name} ${product.slug} ${product.category}`.toLowerCase().includes(search.toLowerCase()) && (filter === "all" || product.status === filter)), [products, search, filter]);
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="text-2xl font-semibold text-white">Product management</h2><p className="mt-1 text-sm text-white/45">Create and publish the inventory your customers can actually buy.</p></div><div className="flex flex-wrap gap-2"><label className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.04] px-3 text-white/45"><Search size={14} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search products" className="w-32 bg-transparent py-2.5 text-xs text-white outline-none" /></label><select value={filter} onChange={(event) => setFilter(event.target.value)} className="rounded-xl border border-white/10 bg-[#0b1b2d] px-3 py-2.5 text-xs text-white"><option value="all">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><AdminButton tone="light" onClick={() => onEdit()}><Plus size={15} /> New product</AdminButton></div></div>{query.isLoading ? <LoadingCard /> : products.length === 0 ? <EmptyCard title="No products" detail="Create the first website product to populate the marketplace." /> : <div className="overflow-hidden rounded-[24px] border border-white/10 bg-[#0a1b2d]/70"><div className="hidden grid-cols-[1.5fr_.8fr_.55fr_.7fr_auto] gap-4 border-b border-white/10 px-5 py-4 font-mono text-[9px] uppercase tracking-[.16em] text-white/35 md:grid"><span>Product</span><span>Category</span><span>Price</span><span>Status</span><span>Actions</span></div>{visibleProducts.map((product: any) => <div key={product.id} className="grid gap-4 border-b border-white/10 px-5 py-5 last:border-0 md:grid-cols-[1.5fr_.8fr_.55fr_.7fr_auto] md:items-center"><div className="flex items-center gap-4"><img src={product.heroImage} alt={`${product.name} preview`} className="h-12 w-16 rounded-lg object-cover" /><div><div className="font-semibold text-white">{product.name}</div><div className="mt-1 font-mono text-[10px] text-white/35">/{product.slug}</div></div></div><div className="text-sm text-white/55">{product.category}</div><div className="font-mono text-sm text-white/70">{product.currency} {Number(product.price).toLocaleString("en-US")}</div><div><StatusPill status={product.status} />{product.demoStatus === "healthy" ? <span className="font-mono text-[9px] text-emerald-300">DEMO LIVE</span> : product.demoUrl ? <span className="font-mono text-[9px] text-amber-300">DEMO UNVERIFIED</span> : <span className="font-mono text-[9px] text-white/30">NO DEMO</span>}</div><div className="flex flex-wrap gap-2"><AdminButton onClick={() => onEdit(product)}><FilePenLine size={14} /> Edit</AdminButton>{product.demoUrl && <AdminButton onClick={() => demoCheck.mutate({ productId: product.id })} disabled={demoCheck.isPending}><RefreshCcw size={14} /> Verify demo</AdminButton>}{product.status === "published" ? <AdminButton onClick={() => statusMutation.mutate({ productId: product.id, status: "archived" })}><Archive size={14} /> Archive</AdminButton> : <AdminButton onClick={() => statusMutation.mutate({ productId: product.id, status: "published" })}><Check size={14} /> Publish</AdminButton>}{product.status !== "published" && <AdminButton tone="danger" onClick={() => { if (window.confirm(`Delete ${product.name}? Products with order history must be archived.`)) deleteMutation.mutate({ productId: product.id }); }}><Trash2 size={14} /> Delete</AdminButton>}</div></div>)}</div>}</div>;
}

function OrdersPanel() {
  const query = trpc.admin.orders.useQuery();
  const utils = trpc.useUtils();
  const statusMutation = trpc.admin.orderStatus.useMutation({ onSuccess: () => { toast.success("Order status updated"); utils.admin.orders.invalidate(); utils.admin.overview.invalidate(); }, onError: (e) => toast.error("Order update failed", { description: e.message }) });
  const [search, setSearch] = useState(""); const [filter, setFilter] = useState("all");
  const rows = useMemo(() => (query.data ?? []).filter((row: any) => { const haystack = `${row.order.id} ${row.user.email ?? ""} ${row.user.name ?? ""} ${row.item?.productName ?? ""}`.toLowerCase(); return haystack.includes(search.toLowerCase()) && (filter === "all" || row.order.status === filter); }), [query.data, search, filter]);
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><h2 className="text-2xl font-semibold text-white">Order control</h2><p className="mt-1 text-sm text-white/45">Inspect customers, payment state, and fulfillment without bypassing verification.</p></div><div className="flex flex-wrap gap-2"><label className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.04] px-3 text-white/45"><Search size={14} /><input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search orders" className="w-32 bg-transparent py-2.5 text-xs text-white outline-none" /></label><label className="flex items-center gap-2 rounded-xl border border-white/10 bg-white/[.04] px-3 text-white/45"><Filter size={14} /><select value={filter} onChange={(e) => setFilter(e.target.value)} className="bg-transparent py-2.5 text-xs text-white outline-none"><option value="all">All statuses</option><option value="pending">Pending</option><option value="paid">Paid</option><option value="fulfilled">Fulfilled</option><option value="cancelled">Cancelled</option></select></label></div></div>{query.isLoading ? <LoadingCard /> : rows.length === 0 ? <EmptyCard title="No matching orders" detail="Orders will appear here once customers create them." /> : <div className="overflow-x-auto rounded-[24px] border border-white/10 bg-[#0a1b2d]/70"><table className="w-full min-w-[920px] text-left"><thead className="border-b border-white/10 font-mono text-[9px] uppercase tracking-[.15em] text-white/35"><tr><th className="px-5 py-4">Order</th><th>Customer</th><th>Item</th><th>Payment</th><th>Status</th><th className="pr-5">Action</th></tr></thead><tbody>{rows.map((row: any) => <tr key={`${row.order.id}-${row.item?.id ?? "empty"}`} className="border-b border-white/10 last:border-0"><td className="px-5 py-5"><div className="font-mono text-sm text-white">#{row.order.id}</div><div className="mt-1 text-[10px] text-white/35">{new Date(row.order.createdAt).toLocaleDateString()}</div></td><td><div className="text-sm text-white/75">{row.user.name || "Unnamed"}</div><div className="mt-1 text-xs text-white/35">{row.user.email || "No email"}</div></td><td className="text-sm text-white/65">{row.item?.productName ?? "—"}</td><td><StatusPill status={row.payment?.status ?? "pending"} /><div className="mt-1 font-mono text-[10px] text-white/35">{row.order.currency} {Number(row.order.subtotal).toLocaleString("en-US")}</div></td><td><StatusPill status={row.order.status} /></td><td className="pr-5">{row.order.status === "pending" ? <AdminButton tone="danger" onClick={() => statusMutation.mutate({ orderId: row.order.id, status: "cancelled" })}>Cancel order</AdminButton> : row.order.status === "paid" ? <AdminButton onClick={() => statusMutation.mutate({ orderId: row.order.id, status: "fulfilled" })}><PackageCheck size={14} /> Fulfill</AdminButton> : <span className="text-xs text-white/30">No action</span>}</td></tr>)}</tbody></table></div>}</div>;
}

function DeliveriesPanel() {
  const query = trpc.admin.deliveries.useQuery();
  const utils = trpc.useUtils();
  const update = trpc.admin.deliveryUpdate.useMutation({ onSuccess: () => { toast.success("Delivery record updated"); utils.admin.deliveries.invalidate(); }, onError: (e) => toast.error("Delivery update failed", { description: e.message }) });
  const [editing, setEditing] = useState<any | null>(null);
  return <div className="space-y-5"><div className="flex items-center justify-between"><div><h2 className="text-2xl font-semibold text-white">Delivery center</h2><p className="mt-1 text-sm text-white/45">Track instance provisioning, access links, source, docs, and license readiness.</p></div><AdminButton onClick={() => query.refetch()}><RefreshCcw size={14} /> Refresh</AdminButton></div>{query.isLoading ? <LoadingCard /> : query.data?.length ? <div className="space-y-4">{query.data.map((row: any) => <article key={row.delivery.id} className="rounded-[24px] border border-white/10 bg-[#0a1b2d]/70 p-5 md:p-7"><div className="flex flex-col justify-between gap-5 md:flex-row md:items-start"><div className="flex items-center gap-4"><div className="grid h-12 w-12 place-items-center rounded-xl bg-[#2d7ff9]/15 text-[#83c2ff]"><Truck size={20} /></div><div><div className="font-semibold text-white">{row.product.name}</div><div className="mt-1 text-xs text-white/40">Order customer: {row.user.name || row.user.email || `User #${row.user.id}`}</div></div></div><div className="flex items-center gap-3"><StatusPill status={row.delivery.status} /><AdminButton onClick={() => setEditing(row)}><FilePenLine size={14} /> Manage delivery</AdminButton></div></div><div className="mt-7 grid gap-3 sm:grid-cols-3">{[["Website instance", row.delivery.instanceUrl, Link2], ["Admin panel", row.delivery.adminUrl, LayoutDashboard], ["Source + docs + license", [row.delivery.sourceReady, row.delivery.documentationReady, row.delivery.licenseReady].filter(Boolean).length === 3 ? "Ready" : "In progress", ShieldCheck]].map(([label, value, Icon]: any) => <div key={label} className="rounded-2xl bg-white/[.04] p-4"><div className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-[.14em] text-white/35"><Icon size={13} /> {label}</div>{typeof value === "string" && value.startsWith("http") ? <a className="mt-3 block truncate text-xs text-[#83c2ff]" href={value} target="_blank" rel="noreferrer">{value}</a> : <div className="mt-3 text-sm text-white/65">{value || "Not configured"}</div>}</div>)}</div></article>)}</div> : <EmptyCard title="No delivery records" detail="Delivery records appear after a verified purchase is provisioned." />}{editing && <DeliveryEditor row={editing} onClose={() => setEditing(null)} onSaved={() => { setEditing(null); query.refetch(); }} update={update} />}</div>;
}

function DeliveryEditor({ row, onClose, onSaved, update }: { row: any; onClose: () => void; onSaved: () => void; update: ReturnType<typeof trpc.admin.deliveryUpdate.useMutation> }) {
  const [status, setStatus] = useState(row.delivery.status); const [instanceUrl, setInstanceUrl] = useState(row.delivery.instanceUrl ?? ""); const [adminUrl, setAdminUrl] = useState(row.delivery.adminUrl ?? ""); const [sourceReady, setSourceReady] = useState(Boolean(row.delivery.sourceReady)); const [documentationReady, setDocumentationReady] = useState(Boolean(row.delivery.documentationReady)); const [licenseReady, setLicenseReady] = useState(Boolean(row.delivery.licenseReady));
  const save = () => update.mutate({ deliveryId: row.delivery.id, status, instanceUrl: instanceUrl || null, adminUrl: adminUrl || null, sourceReady, documentationReady, licenseReady }, { onSuccess: onSaved });
  return <div className="fixed inset-0 z-50 grid place-items-center bg-[#06111f]/85 p-4 backdrop-blur-md"><div className="w-full max-w-xl rounded-[28px] border border-white/15 bg-[#0a1b2d] p-6 md:p-8"><div className="flex items-start justify-between"><div><div className="font-mono text-[10px] uppercase tracking-[.2em] text-[#83c2ff]">Delivery #{row.delivery.id}</div><h2 className="mt-3 text-2xl font-semibold text-white">{row.product.name}</h2></div><button type="button" onClick={onClose} className="rounded-full border border-white/15 p-2 text-white/50"><X size={17} /></button></div><div className="mt-7 space-y-5"><label className="block space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">Status</span><select value={status} onChange={(e) => setStatus(e.target.value)} className="w-full rounded-xl border border-white/10 bg-[#0b1b2d] px-3.5 py-3 text-sm text-white"><option value="queued">Queued</option><option value="provisioning">Provisioning</option><option value="ready">Ready</option><option value="blocked">Blocked</option></select></label><div className="grid gap-4 md:grid-cols-2">{[["Website instance", instanceUrl, setInstanceUrl], ["Admin panel", adminUrl, setAdminUrl]].map(([label, value, setter]: any) => <label key={label} className="space-y-2"><span className="font-mono text-[10px] uppercase tracking-[.14em] text-white/40">{label} URL</span><input value={value} onChange={(e) => setter(e.target.value)} placeholder="https://…" className="w-full rounded-xl border border-white/10 bg-white/[.04] px-3.5 py-3 text-sm text-white outline-none focus:border-[#83c2ff]/70" /></label>)}</div><div className="space-y-3">{[["Source package ready", sourceReady, setSourceReady], ["Documentation ready", documentationReady, setDocumentationReady], ["License ready", licenseReady, setLicenseReady]].map(([label, value, setter]: any) => <label key={label} className="flex items-center gap-3 rounded-xl bg-white/[.04] p-4 text-sm text-white/70"><input type="checkbox" checked={value} onChange={(e) => setter(e.target.checked)} className="h-4 w-4 accent-[#83c2ff]" /> {label}</label>)}</div><div className="flex justify-end gap-3 border-t border-white/10 pt-5"><AdminButton onClick={onClose}>Cancel</AdminButton><AdminButton tone="light" onClick={save} disabled={update.isPending}>{update.isPending ? "Saving…" : "Save delivery"}</AdminButton></div></div></div></div>;
}

function CouponsPanel() {
  const query = trpc.admin.coupons.useQuery();
  const utils = trpc.useUtils();
  const [code, setCode] = useState(""); const [discountType, setDiscountType] = useState<"percent" | "fixed">("percent"); const [discountValue, setDiscountValue] = useState("");
  const create = trpc.admin.couponCreate.useMutation({ onSuccess: () => { toast.success("Coupon created"); setCode(""); setDiscountValue(""); utils.admin.coupons.invalidate(); }, onError: (e) => toast.error("Coupon was not created", { description: e.message }) });
  const update = trpc.admin.couponUpdate.useMutation({ onSuccess: () => utils.admin.coupons.invalidate(), onError: (e) => toast.error("Coupon update failed", { description: e.message }) });
  return <div className="space-y-5"><div><h2 className="text-2xl font-semibold text-white">Coupon control</h2><p className="mt-1 text-sm text-white/45">Create and pause discount codes. Validation stays server-side before payment.</p></div><form onSubmit={(event) => { event.preventDefault(); create.mutate({ code, discountType, discountValue, expiresAt: null, maxUses: null }); }} className="glass grid gap-3 rounded-[24px] p-5 md:grid-cols-[1fr_.7fr_.7fr_auto]"><input required value={code} onChange={(e) => setCode(e.target.value)} placeholder="CODE" className="rounded-xl border border-white/10 bg-white/[.04] px-3 py-2.5 text-sm uppercase text-white outline-none" /><select value={discountType} onChange={(e) => setDiscountType(e.target.value as "percent" | "fixed")} className="rounded-xl border border-white/10 bg-[#0b1b2d] px-3 py-2.5 text-sm text-white"><option value="percent">Percent</option><option value="fixed">Fixed EUR</option></select><input required value={discountValue} onChange={(e) => setDiscountValue(e.target.value)} placeholder="10.00" className="rounded-xl border border-white/10 bg-white/[.04] px-3 py-2.5 text-sm text-white outline-none" /><AdminButton type="submit" tone="light" disabled={create.isPending}><Tag size={14} /> Create</AdminButton></form>{query.isLoading ? <LoadingCard /> : query.data?.length ? <div className="space-y-3">{query.data.map((coupon: any) => <div key={coupon.id} className="flex flex-col justify-between gap-4 rounded-2xl border border-white/10 bg-[#0a1b2d]/70 p-5 sm:flex-row sm:items-center"><div><div className="font-mono text-sm text-white">{coupon.code}</div><div className="mt-1 text-xs text-white/45">{coupon.discountType === "percent" ? `${coupon.discountValue}% off` : `€${coupon.discountValue} off`} · used {coupon.usedCount}{coupon.maxUses ? ` / ${coupon.maxUses}` : ""}</div></div><AdminButton onClick={() => update.mutate({ couponId: coupon.id, active: !coupon.active, expiresAt: coupon.expiresAt, maxUses: coupon.maxUses })}>{coupon.active ? "Pause" : "Activate"}</AdminButton></div>)}</div> : <EmptyCard title="No coupons" detail="Create a code for a controlled launch offer." />}</div>;
}

function ReviewsPanel() {
  const query = trpc.admin.reviews.useQuery();
  const utils = trpc.useUtils();
  const status = trpc.admin.reviewStatus.useMutation({ onSuccess: () => { toast.success("Review status updated"); utils.admin.reviews.invalidate(); }, onError: (e) => toast.error("Review update failed", { description: e.message }) });
  return <div className="space-y-5"><div><h2 className="text-2xl font-semibold text-white">Review moderation</h2><p className="mt-1 text-sm text-white/45">Only verified purchasers can submit reviews; publication remains an owner decision.</p></div>{query.isLoading ? <LoadingCard /> : query.data?.length ? <div className="space-y-3">{query.data.map((row: any) => <article key={row.review.id} className="rounded-2xl border border-white/10 bg-[#0a1b2d]/70 p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-start"><div><div className="flex items-center gap-2 text-white"><Star size={15} className="text-[#ef8b65]" /> {row.review.rating}/5 · {row.product.name}</div><div className="mt-2 text-sm font-semibold text-white/80">{row.review.title || "Untitled review"}</div><p className="mt-2 max-w-2xl text-sm leading-6 text-white/50">{row.review.body || "No review body."}</p><div className="mt-3 text-xs text-white/30">by {row.user.name || row.user.email || `User #${row.user.id}`}</div></div><div className="flex flex-wrap items-center gap-2"><StatusPill status={row.review.status} />{row.review.status !== "published" && <AdminButton onClick={() => status.mutate({ reviewId: row.review.id, status: "published" })}><Check size={14} /> Publish</AdminButton>}{row.review.status !== "hidden" && <AdminButton tone="danger" onClick={() => status.mutate({ reviewId: row.review.id, status: "hidden" })}>Hide</AdminButton>}</div></div></article>)}</div> : <EmptyCard title="No reviews" detail="Verified customer reviews will appear here for moderation." />}</div>;
}

function CategoriesPanel() {
  const query = trpc.admin.categories.useQuery(); const utils = trpc.useUtils();
  const [editing, setEditing] = useState<any | null>(null); const [name, setName] = useState(""); const [slug, setSlug] = useState(""); const [description, setDescription] = useState(""); const [status, setStatus] = useState<"draft" | "published" | "archived">("published");
  const reset = () => { setEditing(null); setName(""); setSlug(""); setDescription(""); setStatus("published"); };
  const startEdit = (category: any) => { setEditing(category); setName(category.name); setSlug(category.slug); setDescription(category.description ?? ""); setStatus(category.status); };
  const create = trpc.admin.categoryCreate.useMutation({ onSuccess: () => { toast.success("Category created"); utils.admin.categories.invalidate(); reset(); }, onError: (e) => toast.error("Category was not created", { description: e.message }) });
  const update = trpc.admin.categoryUpdate.useMutation({ onSuccess: () => { toast.success("Category updated"); utils.admin.categories.invalidate(); reset(); }, onError: (e) => toast.error("Category was not updated", { description: e.message }) });
  const statusMutation = trpc.admin.categoryStatus.useMutation({ onSuccess: () => { utils.admin.categories.invalidate(); }, onError: (e) => toast.error("Category status failed", { description: e.message }) });
  const remove = trpc.admin.categoryDelete.useMutation({ onSuccess: () => { toast.success("Category deleted"); utils.admin.categories.invalidate(); }, onError: (e) => toast.error("Category was not deleted", { description: e.message }) });
  const reorder = trpc.admin.categoryReorder.useMutation({ onSuccess: () => utils.admin.categories.invalidate(), onError: (e) => toast.error("Category order failed", { description: e.message }) });
  const save = (event: React.FormEvent) => { event.preventDefault(); const data = { name, slug, description: description || null, status, sortOrder: editing?.sortOrder ?? ((query.data ?? []).length + 1) * 10 }; if (editing) update.mutate({ categoryId: editing.id, data }); else create.mutate(data); };
  const move = (index: number, direction: -1 | 1) => { const categories = [...(query.data ?? [])]; const target = index + direction; if (target < 0 || target >= categories.length) return; [categories[index], categories[target]] = [categories[target], categories[index]]; reorder.mutate({ items: categories.map((category, order) => ({ categoryId: category.id, sortOrder: (order + 1) * 10 })) }); };
  return <div className="space-y-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><h2 className="text-2xl font-semibold text-white">Category system</h2><p className="mt-1 text-sm text-white/45">One database taxonomy connects owner decisions to the public showroom.</p></div><AdminButton onClick={reset}><Plus size={14} /> New category</AdminButton></div><form onSubmit={save} className="glass grid gap-3 rounded-[24px] p-5 md:grid-cols-[1fr_1fr_1.3fr_.7fr_auto]"><input required value={name} onChange={(e) => setName(e.target.value)} placeholder="Category name" className="rounded-xl border border-white/10 bg-white/[.04] px-3 py-2.5 text-sm text-white outline-none" /><input required pattern="[a-z0-9-]+" value={slug} onChange={(e) => setSlug(e.target.value)} placeholder="slug" className="rounded-xl border border-white/10 bg-white/[.04] px-3 py-2.5 font-mono text-sm text-white outline-none" /><input value={description} onChange={(e) => setDescription(e.target.value)} placeholder="Description" className="rounded-xl border border-white/10 bg-white/[.04] px-3 py-2.5 text-sm text-white outline-none" /><select value={status} onChange={(e) => setStatus(e.target.value as any)} className="rounded-xl border border-white/10 bg-[#0b1b2d] px-3 py-2.5 text-sm text-white"><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><div className="flex gap-2"><AdminButton type="submit" tone="light">{editing ? "Save" : "Create"}</AdminButton>{editing && <AdminButton onClick={reset}>Cancel</AdminButton>}</div></form>{query.isLoading ? <LoadingCard /> : query.data?.length ? <div className="overflow-hidden rounded-[24px] border border-white/10 bg-[#0a1b2d]/70">{query.data.map((category: any, index: number) => <div key={category.id} className="flex flex-col justify-between gap-4 border-b border-white/10 px-5 py-5 last:border-0 sm:flex-row sm:items-center"><div className="flex items-center gap-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#ef8b65]/10 text-[#ef8b65]"><FolderTree size={17} /></div><div><div className="font-semibold text-white">{category.name}</div><div className="mt-1 font-mono text-[10px] text-white/35">/{category.slug} · order {category.sortOrder}</div></div></div><div className="flex flex-wrap items-center gap-2"><StatusPill status={category.status} /><AdminButton onClick={() => move(index, -1)} disabled={index === 0}>↑</AdminButton><AdminButton onClick={() => move(index, 1)} disabled={index === query.data!.length - 1}>↓</AdminButton><AdminButton onClick={() => startEdit(category)}><FilePenLine size={14} /> Edit</AdminButton>{category.status === "published" ? <AdminButton onClick={() => statusMutation.mutate({ categoryId: category.id, status: "archived" })}>Archive</AdminButton> : <AdminButton onClick={() => statusMutation.mutate({ categoryId: category.id, status: "published" })}>Publish</AdminButton>}<AdminButton tone="danger" onClick={() => { if (window.confirm(`Delete ${category.name}? Assigned products must be moved first.`)) remove.mutate({ categoryId: category.id }); }}><Trash2 size={14} /> Delete</AdminButton></div></div>)}</div> : <EmptyCard title="No categories" detail="Create the first database category to shape the showroom." />}</div>;
}

function LoadingCard() { return <div className="h-40 animate-pulse rounded-[24px] border border-white/10 bg-white/[.04]" />; }
function EmptyCard({ title, detail }: { title: string; detail: string }) { return <div className="rounded-[24px] border border-dashed border-white/15 bg-white/[.03] p-10 text-center"><CircleAlert className="mx-auto mb-5 text-white/25" size={22} /><h3 className="text-lg font-semibold text-white">{title}</h3><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-white/45">{detail}</p></div>; }


function SystemTruthPanel() {
  const truth = trpc.admin.systemTruth.useQuery(undefined, { refetchInterval: 60_000 });
  const rows = truth.data?.integrations ?? [];
  const tone = (s: string) => s === "CONNECTED" ? "bg-emerald-400/10 text-emerald-300" : s === "NOT_CONFIGURED" ? "bg-amber-400/10 text-amber-200" : s === "ERROR" ? "bg-red-400/10 text-red-300" : "bg-white/10 text-white/60";
  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-semibold text-white">System Truth</h2>
        <p className="mt-2 max-w-2xl text-sm text-white/50">
          Live configuration status. CONNECTED only means required env is present (and database probe when applicable). It does not invent provider success.
        </p>
        {truth.data?.generatedAt && (
          <p className="mt-1 font-mono text-[10px] text-white/35">Checked {truth.data.generatedAt}</p>
        )}
      </div>
      {truth.isLoading ? (
        <div className="glass h-40 animate-pulse rounded-2xl" />
      ) : (
        <div className="grid gap-3 md:grid-cols-2">
          {rows.map((row: any) => (
            <div key={row.id} className="glass rounded-2xl p-5">
              <div className="flex items-start justify-between gap-3">
                <div>
                  <h3 className="font-semibold text-white">{row.name}</h3>
                  <p className="mt-2 text-xs leading-5 text-white/50">{row.detail}</p>
                  {row.error && <p className="mt-2 text-xs text-red-300">{row.error}</p>}
                  <p className="mt-3 font-mono text-[10px] text-white/35">{(row.requiredEnv || []).join(" · ")}</p>
                </div>
                <span className={`shrink-0 rounded-full px-2.5 py-1 font-mono text-[9px] uppercase tracking-[.12em] ${tone(row.status)}`}>{row.status}</span>
              </div>
            </div>
          ))}
        </div>
      )}
      {truth.data?.payments && (
        <div className="glass rounded-2xl p-5 text-sm text-white/60">
          <div className="font-semibold text-white">Checkout providers</div>
          <p className="mt-2 font-mono text-xs">
            stripe={String(truth.data.payments.stripe)} · chargily={String(truth.data.payments.chargily)} · paypal={String(truth.data.payments.paypal)}
          </p>
          <p className="mt-3 font-mono text-xs">
            native={String(truth.data.provisioning?.native)} · external={String(truth.data.provisioning?.external)} · manual={String(truth.data.provisioning?.manual)}
          </p>
        </div>
      )}
    </div>
  );
}

export default function Admin() {
  const { user, loading, isAuthenticated, logout } = useAuth();
  const [tab, setTab] = useState<Tab>("overview"); const [editor, setEditor] = useState<any | null | false>(false);
  const overviewQuery = trpc.admin.overview.useQuery(undefined, { enabled: isAuthenticated && user?.role === "admin" });
  if (loading) return <div className="numi-shell min-h-screen bg-[#06111f] p-10 text-white/50">Checking owner access…</div>;
  if (!isAuthenticated || user?.role !== "admin") return <div className="numi-shell min-h-screen bg-[#06111f]"><SiteNav /><main className="mx-auto max-w-2xl px-5 py-20 md:px-10"><div className="glass rounded-[28px] p-8 md:p-12"><LockKeyhole className="mb-7 text-[#ef8b65]" size={26} /><h1 className="text-4xl font-semibold tracking-[-.06em] text-white">Owner access only.</h1><p className="mt-4 text-sm leading-7 text-white/50">This route is protected server-side. Sign in with the owner account to inspect the marketplace operations layer.</p><Link href="/" className="mt-8 inline-flex text-sm text-[#83c2ff]">Return to showroom</Link></div></main></div>;
  const nav: Array<[Tab, string, any]> = [["overview", "Overview", LayoutDashboard], ["products", "Products", Boxes], ["categories", "Categories", FolderTree], ["orders", "Orders", CreditCard], ["deliveries", "Deliveries", Truck], ["coupons", "Coupons", Tag], ["reviews", "Reviews", Star], ["system", "System Truth", Database]];
  return <div className="numi-shell min-h-screen bg-[#06111f] text-white"><div className="flex min-h-screen"><aside className="hidden w-64 shrink-0 border-r border-white/10 bg-[#071526] p-5 lg:flex lg:flex-col"><Link href="/" className="mb-12 flex items-center gap-3"><span className="grid h-8 w-8 place-items-center rounded-full border border-white/25 text-sm font-bold">N</span><span className="font-mono text-sm tracking-[.3em] text-white/85">NUMI</span></Link><div className="mb-4 font-mono text-[9px] uppercase tracking-[.2em] text-white/30">Owner space</div><nav className="space-y-1">{nav.map(([key, label, Icon]) => <button type="button" key={key} onClick={() => setTab(key)} className={`flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition ${tab === key ? "bg-[#2d7ff9]/15 text-[#9bceff]" : "text-white/50 hover:bg-white/[.05] hover:text-white"}`}><Icon size={16} /> {label}</button>)}</nav><div className="mt-auto space-y-4"><div className="rounded-2xl border border-emerald-400/20 bg-emerald-400/[.06] p-4"><div className="flex items-center gap-2 font-mono text-[9px] uppercase tracking-[.15em] text-emerald-300"><span className="h-2 w-2 rounded-full bg-emerald-300" /> Secure session</div><p className="mt-3 text-xs leading-5 text-white/40">Actions are audit logged.</p></div><button type="button" onClick={() => logout()} className="flex items-center gap-2 px-3 text-xs text-white/40 hover:text-white"><LogOut size={14} /> Sign out</button></div></aside><main className="min-w-0 flex-1"><div className="lg:hidden"><SiteNav /></div><div className="mx-auto max-w-[1500px] px-5 py-6 md:px-10 md:py-10"><div className="mb-9 flex flex-col justify-between gap-6 border-b border-white/10 pb-8 md:flex-row md:items-end"><div><div className="mb-4 flex items-center gap-3 font-mono text-[10px] uppercase tracking-[.22em] text-[#ef8b65]"><span>Owner space</span><span className="h-px w-8 bg-[#ef8b65]" /> Operations</div><h1 className="text-4xl font-semibold tracking-[-.07em] text-white md:text-6xl">{tab === "overview" ? "Keep the signal clear." : tab[0].toUpperCase() + tab.slice(1)}</h1><p className="mt-4 max-w-2xl text-sm leading-7 text-white/45">{tab === "products" ? "Manage the inventory and publishing state of every website product." : tab === "orders" ? "Search order history and control safe fulfillment transitions." : tab === "deliveries" ? "Turn a verified purchase into a clear, independent customer handover." : tab === "categories" ? "Control the live taxonomy shared by products and the public showroom." : tab === "coupons" ? "Create and pause controlled launch offers." : tab === "reviews" ? "Moderate verified customer feedback." : "A focused command layer for the owner-operated NUMI marketplace."}</p></div><div className="flex items-center gap-2 rounded-full border border-white/10 bg-white/[.03] px-3 py-2 font-mono text-[10px] uppercase tracking-[.14em] text-white/45"><span className="h-2 w-2 rounded-full bg-emerald-300" /> {user.name || "Owner"}</div></div><div className="mb-7 flex gap-2 overflow-x-auto lg:hidden">{nav.map(([key, label, Icon]) => <button type="button" key={key} onClick={() => setTab(key)} className={`flex shrink-0 items-center gap-2 rounded-xl border px-3 py-2 text-xs ${tab === key ? "border-[#83c2ff]/50 bg-[#2d7ff9]/15 text-[#9bceff]" : "border-white/10 text-white/45"}`}><Icon size={14} /> {label}</button>)}</div>{tab === "overview" && <Overview overview={overviewQuery.data} onNavigate={setTab} />}{tab === "products" && <ProductsPanel onEdit={(product) => setEditor(product ?? null)} />}{tab === "categories" && <CategoriesPanel />}{tab === "orders" && <OrdersPanel />}{tab === "deliveries" && <DeliveriesPanel />}{tab === "coupons" && <CouponsPanel />}{tab === "system" && <SystemTruthPanel />}{tab === "reviews" && <ReviewsPanel />}</div></main></div>{editor !== false && <ProductEditor initial={editor || undefined} onClose={() => setEditor(false)} onSaved={() => {}} />}</div>;
}
